// nextMasterSonyflakeGpayID generates a fresh, table-independent Sonyflake _gpay_id
// for a newly inserted row on a Master table. Existing rows on Master keep their
// original _gpay_id because ON CONFLICT (<pk>) DO UPDATE never overwrites _gpay_id.
func nextMasterSonyflakeGpayID() int64 {
	id, err := idgen.NextID()
	if err != nil {
		idgen.Init(zap.NewNop())
		id, err = idgen.NextID()
	}
	if err == nil && id > 0 {
		return int64(id & 0x7FFFFFFFFFFFFFFF)
	}
	return time.Now().UnixNano() & 0x7FFFFFFFFFFFFFFF
}

