func (r MasterBindingRef) ShadowRel() string { return r.ShadowSchema + "." + r.ShadowTable }
func (r MasterBindingRef) MasterRel() string { return r.MasterSchema + "." + r.MasterTable }

// ResolveSegmentBPKPair resolves the business key pair between Shadow and Master for Segment B:
// - Shadow side uses "_source_id"
// - Master side uses transform_spec.pk (e.g. "_id" or "id")
// - Only when transform_spec.pk is empty (e.g. flatten) does it fallback to ("_gpay_id", "_gpay_id", "gpay").
func ResolveSegmentBPKPair(ctx context.Context, ref MasterBindingRef, msAgent *ReconDestAgent) (shadowPKCol, masterPKCol, idType string) {
	if strings.TrimSpace(ref.TransformSpec) != "" {
		var spec struct {
			PK string `json:"pk"`
		}
		if err := json.Unmarshal([]byte(ref.TransformSpec), &spec); err == nil {
			pk := strings.TrimSpace(spec.PK)
			if pk != "" && pk != segBPKColumn && validateIdent(pk) == nil {
				masterOK := true
				if msAgent != nil && ref.MasterTable != "" {
					if ok, err := msAgent.ColumnExists(ctx, ref.MasterRel(), pk); err != nil || !ok {
						masterOK = false
					}
				}
				if masterOK {
					return "_source_id", pk, "id"
				}
			}
		}
	}

